<?php require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('commissions.view'); $from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??today();$bid=current_branch_id();$rows=all('SELECT c.*,st.full_name staff,s.invoice_no,sv.name service FROM commissions c JOIN staff st ON st.id=c.staff_id JOIN sales s ON s.id=c.sale_id LEFT JOIN services sv ON sv.id=c.service_id WHERE c.branch_id=? AND DATE(c.created_at) BETWEEN ? AND ? ORDER BY c.id DESC',[$bid,$from,$to]);$title='Staff Commission Report';$subtitle='Automatic commission calculated after payment.';include dirname(__DIR__).'/includes/header.php';?><div class="toolbar"><form><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn light">Filter</button></form></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Invoice</th><th>Staff</th><th>Service</th><th>Base</th><th>Rule</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php $sum=0; foreach($rows as $r):$sum+=(float)$r['commission_amount'];?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['invoice_no'])?></td><td><?=e($r['staff'])?></td><td><?=e($r['service'])?></td><td><?=money($r['base_amount'])?></td><td><?=e($r['commission_type'])?> <?=e($r['commission_value'])?></td><td><?=money($r['commission_amount'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?><tr><th colspan="6">Total</th><th><?=money($sum)?></th><th></th></tr></tbody></table></div><?php include dirname(__DIR__).'/includes/footer.php'; ?>